import{_ as e,o as a,c as s,Q as n}from"./chunks/framework.48927342.js";const f=JSON.parse('{"title":"00 Editorial Requirements","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/grammar/00-requirements.md","filePath":"en/more/maltese/grammar/00-requirements.md"}'),i={name:"en/more/maltese/grammar/00-requirements.md"},o=n('<h1 id="_00-editorial-requirements" tabindex="-1">00 Editorial Requirements <a class="header-anchor" href="#_00-editorial-requirements" aria-label="Permalink to &quot;00 Editorial Requirements&quot;">​</a></h1><p>This page records the goals and coverage requirements for this beginner Maltese resource.</p><p>The learner is studying Maltese and wants a set of Markdown documents, with one file per topic and a separate index. The requested topics are:</p><ul><li>Basic vocabulary, organized in tables by category: pronouns, question words, common verbs, prepositions, family and friends, home, animals, plants, transport, and time. Major categories should have at least 20 examples. Include English and Maltese; show relevant singular/plural forms directly in the tables, and separate male/female animal terms where applicable. Family vocabulary should include detailed relationships. Order time expressions from hours through days, weeks, months, and years. Sort question words and prepositions approximately by frequency.</li><li>200 useful phrases in categories of at least 20 examples each, in English and Maltese.</li><li>Person-based verb conjugation without tense explanations. Explain the rules, including verbs with initial or medial <code>għ</code>, before giving five common verbs and five examples each of initial- and medial-<code>għ</code> verbs. Show all persons in separate columns. Do not begin with a long list of example sentences.</li><li>Basic tenses, including present, past, and future. Explain each tense and provide common verbs, including verbs with initial and medial <code>għ</code>; show all persons in separate columns and add a simple example for one person. Do not begin with a long list of example sentences.</li><li>Cardinal and ordinal numbers, their grammar, and ten examples of large numbers.</li><li>Time expressions in this order: o&#39;clock, parts of the day and relative days/weeks/months/years, clock times using <code>u</code>, <code>nofs</code>, and <code>neqsin</code>, then durations. Include 20 examples for times of day and 20 for durations; examples should be phrases, not full sentences.</li><li>Dates, including weekdays, months, seasons, relative weeks/months/years, and 20 examples.</li><li>A broad list of prepositions and their uses. Include combinations with <code>il-</code>, <code>l-</code>, <code>is-</code>, <code>id-</code>, and <code>it-</code>, plus example words and sentences ordered approximately by frequency.</li></ul><p>The English edition retains English and Maltese content and omits Chinese from tables.</p>',5),t=[o];function r(l,d,c,m,p,u){return a(),s("div",null,t)}const g=e(i,[["render",r]]);export{f as __pageData,g as default};
